import re
def label_overlay(s):
 if s.count(';')!=1:return None
 base,ops=s.split(';');d={};k=re.compile(r'[a-z][a-z0-9]*(?:-[a-z0-9]+)*');ok=lambda v:bool(v) and all(32<=ord(c)<=126 and c not in ',;' for c in v)
 if base:
  for r in base.split(','):
   p=r.split('=',1)
   if len(p)!=2 or not k.fullmatch(p[0]) or not ok(p[1]) or p[0] in d:return None
   d[p[0]]=p[1]
 if ops:
  for op in ops.split(','):
   if op.startswith('set:'):
    p=op[4:].split('=',1)
    if len(p)!=2 or not k.fullmatch(p[0]) or not ok(p[1]):return None
    d[p[0]]=p[1]
   elif op.startswith('unset:') and k.fullmatch(op[6:]):d.pop(op[6:],None)
   else:return None
 return ','.join(f'{x}={d[x]}' for x in sorted(d))
